INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist eine PUA immer ein Virus?', 2, '[{"text": "Nein", "correct": true, "because": "PUA ist unerwünscht, aber nicht zwangsläufig schädlich"}, {"text": "Ja", "correct": false, "because": "PUA unterscheidet sich von Malware"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Hauptmerkmal einer PUA?', 3, '[{"text": "Ungefragte Installation", "correct": true, "because": "Oft mit Freeware gebündelt"}, {"text": "Hohe Leistung", "correct": false, "because": "PUA verlangsamt oft"}, {"text": "Manuelle Deinstallation", "correct": false, "because": "Oft erschwert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Arten von PUA gibt es?', 5, '[{"text": "Adware", "correct": true, "because": "Zeigt unerwünschte Werbung"}, {"text": "Toolbars", "correct": true, "because": "Ändern Browser-Einstellungen"}, {"text": "Antivirus-Software", "correct": false, "because": "Schützt, statt stört"}, {"text": "Texteditoren", "correct": false, "because": "Produktive Software"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) PUAs sammeln oft Daten. b) Sie sind immer harmlos.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) können Sicherheitsrisiken bergen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Erkennung einer PUA?', 4, '[{"text": "Browser-Veränderungen", "correct": false, "because": "Typisches PUA-Merkmal"}, {"text": "Werbeanzeigen", "correct": false, "because": "Hinweis auf Adware"}, {"text": "Farbcodierung", "correct": true, "because": "Irrelevant für PUA"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob PUAs oft mit Freeware installiert werden?', 2, '[{"text": "Ja", "correct": true, "because": "Gebündelt mit kostenloser Software"}, {"text": "Nein", "correct": false, "because": "Typischer Verbreitungsweg"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie schützt man sich vor PUAs?', 3, '[{"text": "Antivirus-Software", "correct": true, "because": "Erkennt und blockiert PUAs"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Kein Schutzfaktor"}, {"text": "Manuelle Installation", "correct": false, "because": "Vorsicht bei Freeware nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme verursachen PUAs?', 5, '[{"text": "Systemverlangsamung", "correct": true, "because": "Verbrauchen Ressourcen"}, {"text": "Datensammlung", "correct": true, "because": "Ohne Zustimmung"}, {"text": "Höhere Leistung", "correct": false, "because": "PUAs senken Leistung"}, {"text": "Grafische Verbesserung", "correct": false, "because": "Kein PUA-Effekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) PUAs können Browser-Einstellungen ändern. b) Sie sind immer leicht zu entfernen. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) oft erschwert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um PUAs zu vermeiden?', 4, '[{"text": "Vorsicht bei Freeware", "correct": false, "because": "Vermeidet Installation"}, {"text": "Antivirus-Software", "correct": false, "because": "Schützt System"}, {"text": "3D-Modellierung", "correct": true, "because": "Irrelevant für Sicherheit"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind PUAs dasselbe wie Malware?', 2, '[{"text": "Nein", "correct": true, "because": "PUAs weniger schädlich"}, {"text": "Ja", "correct": false, "because": "Unterschiedliche Kategorien"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen helfen gegen PUAs?', 4, '[{"text": "Deinstallation", "correct": true, "because": "Entfernt PUA"}, {"text": "Browser-Reset", "correct": true, "because": "Stellt Einstellungen wieder her"}, {"text": "Höhere Auflösung", "correct": false, "because": "Kein Schutz"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass PUAs immer sichtbar sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Oft im Hintergrund aktiv"}, {"text": "Ja", "correct": false, "because": "Nicht immer offensichtlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, um PUAs zu vermeiden?', 3, '[{"text": "Sorgfältige Installation", "correct": true, "because": "Vermeidet Bündelung"}, {"text": "Maximale Downloads", "correct": false, "because": "Erhöht Risiko"}, {"text": "Manuelle Checks", "correct": false, "because": "Antivirus effizienter"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) PUAs sind oft Adware. b) Sie verbessern die Systemleistung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) verschlechtern Leistung"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Tools helfen gegen PUAs?', 5, '[{"text": "Antivirus-Software", "correct": true, "because": "Erkennt PUAs"}, {"text": "Ad-Blocker", "correct": true, "because": "Reduziert Werbung"}, {"text": "Texteditoren", "correct": false, "because": "Kein Schutz"}, {"text": "Musiksoftware", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einer PUA unwichtig?', 3, '[{"text": "Datensammlung", "correct": false, "because": "Sicherheitsrisiko"}, {"text": "Systemverlangsamung", "correct": false, "because": "Typisches Problem"}, {"text": "Büroausstattung", "correct": true, "because": "Kein IT-Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob PUAs oft Toolbars enthalten?', 2, '[{"text": "Ja", "correct": true, "because": "Häufiges PUA-Merkmal"}, {"text": "Nein", "correct": false, "because": "Toolbars typisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind PUAs rechtlich verboten?', 3, '[{"text": "Nein", "correct": true, "because": "Oft legal, aber unerwünscht"}, {"text": "Ja", "correct": false, "because": "Kein generelles Verbot"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt zu einer PUA?', 4, '[{"text": "Unerwünschte Toolbar im Browser", "correct": true, "because": "Typisches PUA-Verhalten"}, {"text": "Installation eines Texteditors", "correct": false, "because": "Produktive Software"}, {"text": "Netzwerkwartung", "correct": false, "because": "Technische Aufgabe"}]');
